CREATE TABLE rt_cancellation_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, status varchar(24) NOT NULL DEFAULT 'requested', requested_by bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, reason text, penalty_amount numeric(20,6), currency char(3) REFERENCES rt_currencies(code), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE rt_special_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, request_text text NOT NULL, status varchar(24) NOT NULL DEFAULT 'requested', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rt_offline_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, requested_by bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, service_type varchar(32) NOT NULL, description text NOT NULL, status varchar(24) NOT NULL DEFAULT 'submitted', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rt_group_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, requested_by bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, title varchar(255) NOT NULL, guests_count integer, rooms_count integer, status varchar(24) NOT NULL DEFAULT 'submitted', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rt_group_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_request_id uuid NOT NULL REFERENCES rt_group_requests(id) ON DELETE RESTRICT, version integer NOT NULL CHECK(version>0), currency char(3) NOT NULL REFERENCES rt_currencies(code), amount numeric(20,6) NOT NULL CHECK(amount>=0), status varchar(24) NOT NULL DEFAULT 'draft', valid_until timestamptz, UNIQUE(group_request_id,version));
CREATE TABLE rt_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, channel varchar(24) NOT NULL, template_key varchar(120) NOT NULL, locale varchar(2) NOT NULL DEFAULT 'en', status varchar(24) NOT NULL DEFAULT 'queued', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rt_audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id bigint REFERENCES users(id) ON DELETE RESTRICT, company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, action varchar(120) NOT NULL, entity_type varchar(80) NOT NULL, entity_id uuid, request_id varchar(100), occurred_at timestamptz NOT NULL DEFAULT now(), metadata text);
CREATE INDEX rt_audit_events_entity_idx ON rt_audit_events(entity_type,entity_id,occurred_at DESC);
